{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_aad706939ef0ccad8bcd4a49", "claim_ids": ["claim_0727546ba221f30ea7a1d90f", "claim_ee9a1995c02498d62b7e43a2"], "query_ids": ["q_251"], "claims": [{"claim_id": "claim_0727546ba221f30ea7a1d90f", "quote": "Only auto parts for passenger vehicles and light trucks, as defined by Executive Order 14257, issued April 2, 2025, and subject to Section 232 duties as of May 3, 2025, are not subject to the reciprocal duties effective April 5, 2025, pursuant to heading 9903.01.33, HTSUS.", "url": "https://www.cbp.gov/trade/programs-administration/entry-summary/section-232-additional-faqs-autos", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Section 232 duties", "legal_authority": "Executive Order 14257", "affected_product": "auto parts for passenger vehicles and light trucks", "hts_code": "9903.01.33", "duty_rate": "not subject to the reciprocal duties effective April 5, 2025"}}, {"claim_id": "claim_ee9a1995c02498d62b7e43a2", "quote": "Heading 9903.01.33, HTSUS, exempting products subject to Section 232 from the reciprocal tariffs, applies to auto parts for passenger vehicles and light trucks.", "url": "https://www.cbp.gov/trade/programs-administration/entry-summary/section-232-additional-faqs-autos", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Section 232", "affected_product": "auto parts for passenger vehicles and light trucks", "hts_code": "9903.01.33"}}]}, {"pair_id": "conflict_69e9522e307f54312537301f", "claim_ids": ["claim_0bc99fb3d163e036eae5fe0b", "claim_2de1588a853d01b609bf0859"], "query_ids": ["q_253"], "claims": [{"claim_id": "claim_0bc99fb3d163e036eae5fe0b", "quote": "Due to lapse in appropriations and the ensuing cessation of Commission operations, changes pursuant to requests submitted not later than July 15, 2025, are expected to be published in a February 2026 revision to the HTS and effective on the date of publication.", "url": "https://hts.usitc.gov/reststop/file?filename=Preface&release=2026HTSBasic", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"announcement_date": "July 15, 2025", "effective_date": "date of publication", "reported_policy_status": "expected to be published"}}, {"claim_id": "claim_2de1588a853d01b609bf0859", "quote": "Harmonized Tariff Schedule of the United States (2026 Basic Edition) January 1, 2026", "url": "https://hts.usitc.gov/reststop/file?filename=Preface&release=2026HTSBasic", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Harmonized Tariff Schedule of the United States (2026 Basic Edition)", "effective_date": "January 1, 2026"}}]}, {"pair_id": "conflict_79ef765190f383fc3b506c3e", "claim_ids": ["claim_05339ba824bab7aaaae88a87", "claim_06949adb44ec92a388219b44"], "query_ids": ["q_253"], "claims": [{"claim_id": "claim_05339ba824bab7aaaae88a87", "quote": "Harmonized Tariff Schedule of the United States (2026) Annotated for Statistical Reporting Purposes GN p.78 USMCA", "url": "https://hts.usitc.gov/reststop/file?filename=General+Note+11&release=2026HTSBasic", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "USMCA", "legal_authority": "Harmonized Tariff Schedule of the United States (2026)"}}, {"claim_id": "claim_06949adb44ec92a388219b44", "quote": "Harmonized Tariff Schedule of the United States (2026) Annotated for Statistical Reporting Purposes GN p.41 USMCA", "url": "https://hts.usitc.gov/reststop/file?filename=General+Note+11&release=2026HTSBasic", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "USMCA", "legal_authority": "Harmonized Tariff Schedule of the United States (2026)", "announcement_date": "2026"}}]}, {"pair_id": "conflict_1f499168cee93458d17d36e4", "claim_ids": ["claim_32ca8a4a20a2e42f68539e80", "claim_42fb2bf627541474d3fe53ad"], "query_ids": ["q_255"], "claims": [{"claim_id": "claim_32ca8a4a20a2e42f68539e80", "quote": "I determine that aluminum lithographic plates and steel racks constitute aluminum and steel derivative products that should be subject to the applicable derivative tariff under Proclamation 11021.", "url": "https://www.federalregister.gov/documents/2026/06/04/2026-11314/further-adjusting-the-tariff-regimes-for-imports-of-aluminum-steel-and-copper-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Proclamation 11021", "affected_product": "aluminum lithographic plates and steel racks"}}, {"claim_id": "claim_42fb2bf627541474d3fe53ad", "quote": "I determine that aluminum lithographic plates and steel racks constitute aluminum and steel derivative products that should be subject to the applicable derivative tariff under Proclamation 11021.", "url": "https://www.federalregister.gov/documents/2026/06/04/2026-11314/further-adjusting-the-tariff-regimes-for-imports-of-aluminum-steel-and-copper-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Proclamation 11021", "affected_product": "aluminum lithographic plates and steel racks"}}]}, {"pair_id": "conflict_6468b22584bc6cc1825ab77e", "claim_ids": ["claim_c3e065b14ffa4a2085253964", "claim_ff2b4113a57b5b53a2a2932b"], "query_ids": ["q_260"], "claims": [{"claim_id": "claim_c3e065b14ffa4a2085253964", "quote": "USMCA-compliant automobile parts will remain tariff-free until the Secretary of Commerce, in consultation with U.S. Customs and Border Protection (CBP), establishes a process to apply tariffs to their non-U.S. content.", "url": "https://www.whitehouse.gov/fact-sheets/2025/03/fact-sheet-president-donald-j-trump-adjusts-imports-of-automobiles-and-automobile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "USMCA-compliant automobile parts", "legal_authority": "Secretary of Commerce, in consultation with U.S. Customs and Border Protection (CBP)"}}, {"claim_id": "claim_ff2b4113a57b5b53a2a2932b", "quote": "The ad valorem tariff of 25 percent described in clause (1) of this proclamation shall not apply to automobile parts that qualify for preferential treatment under the USMCA until such time that the Secretary, in consultation with CBP, establishes a process to apply the tariff exclusively to the value of the non-U.S. content of such automobile parts and publishes notice in the Federal Register.", "url": "https://www.whitehouse.gov/presidential-actions/2025/03/adjusting-imports-of-automobiles-and-autombile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {}}]}, {"pair_id": "conflict_e0842f9aa2cec3b373bb47d5", "claim_ids": ["claim_0c31254f2320012a8a03c8ce", "claim_f686903d603d134bfc32642b"], "query_ids": ["q_260"], "claims": [{"claim_id": "claim_0c31254f2320012a8a03c8ce", "quote": "Importers of automobiles under the United States-Mexico-Canada Agreement will be given the opportunity to certify their U.S. content and systems will be implemented such that the 25% tariff will only apply to the value of their non-U.S. content.", "url": "https://www.whitehouse.gov/fact-sheets/2025/03/fact-sheet-president-donald-j-trump-adjusts-imports-of-automobiles-and-automobile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "United States-Mexico-Canada Agreement"}}, {"claim_id": "claim_f686903d603d134bfc32642b", "quote": "For automobiles that qualify for preferential tariff treatment under the USMCA, importers of such automobiles may submit documentation to the Secretary identifying the amount of U.S. content in each model imported into the United States.", "url": "https://www.whitehouse.gov/presidential-actions/2025/03/adjusting-imports-of-automobiles-and-autombile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {}}]}, {"pair_id": "conflict_23ad378f20ef3b9afa8046c2", "claim_ids": ["claim_6c9dc3fcb772212ca77c2e8d", "claim_7cc7343ff77dee95cbb1e727"], "query_ids": ["q_261"], "claims": [{"claim_id": "claim_6c9dc3fcb772212ca77c2e8d", "quote": "the body shell, battery pack, and electric drive unit imported from China cannot operate as an electric vehicle and will need to be assembled in Country A with other necessary components", "url": "https://rulings.cbp.gov/ruling/H330647", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"exporting_country": "China"}}, {"claim_id": "claim_7cc7343ff77dee95cbb1e727", "quote": "the country of origin of the subject battery module, part number 41000000, and the battery pack, part number 40007000, for the purposes of Section 301 is China, Japan, or Korea, dependent upon where the battery cells are manufactured.", "url": "https://rulings.cbp.gov/ruling/N329847", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"country_of_origin": "China, Japan, or Korea"}}]}, {"pair_id": "conflict_e866e8cba2e111aa5240ed68", "claim_ids": ["claim_981795600f10a474ec6966a5", "claim_e2ab032169044afe27433d77"], "query_ids": ["q_261"], "claims": [{"claim_id": "claim_981795600f10a474ec6966a5", "quote": "of an electric vehicle (the battery pack, motor, electronics, wiring assemblies, and charger) were of U.S. origin. Based upon these facts, we found that the country of origin of the electric vehicles was the United States.", "url": "https://rulings.cbp.gov/ruling/H229157", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"company": "Vantage Vehicle", "country_of_origin": "United States"}}, {"claim_id": "claim_e2ab032169044afe27433d77", "quote": "of an electric vehicle (the batteries, motor, instrument cluster, wiring assemblies, and heater core) are of U.S. origin. We conclude, based upon these specific facts, that the country of origin of the VVI electric trucks and vans for purposes of U.S. Government procurement is the United States.", "url": "https://rulings.cbp.gov/ruling/H229157", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"company": "VVI"}}]}, {"pair_id": "conflict_c16b4a0ff6c3d2dab342d1f8", "claim_ids": ["claim_1814f1486ad1db5ee5a4fb75", "claim_3c4de2c412b39d8cd81eb5e3"], "query_ids": ["q_262"], "claims": [{"claim_id": "claim_1814f1486ad1db5ee5a4fb75", "quote": "Distributed Processing Technology assembles all the components onto the foreign raw printed circuit board in the United States, and thus the same rationale applies. The board would be substantially transformed.", "url": "https://rulings.cbp.gov/ruling/735306", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"company": "Distributed Processing Technology"}}, {"claim_id": "claim_3c4de2c412b39d8cd81eb5e3", "quote": "With respect to printed circuit boards, Customs has ruled that the complete assembly of all the components onto a printed circuit board was a substantial transformation of the printed circuit board because the assembly process was complex and involved a considerable amount of skill and time.", "url": "https://rulings.cbp.gov/ruling/735306", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"company": "Customs", "legal_authority": "19 CFR 134.35"}}]}, {"pair_id": "conflict_dc5b88758acaea919879aad2", "claim_ids": ["claim_2282ab175a642ad8bd914032", "claim_e3644d42dcd1845f65966b2c"], "query_ids": ["q_262"], "claims": [{"claim_id": "claim_2282ab175a642ad8bd914032", "quote": "CBP held that for purposes of the Generalized System of Preferences (“GSP”), the assembly of a large number of fabricated components onto a printed circuit board in a process involving a considerable amount of time and skill resulted in a substantial transformation.", "url": "https://rulings.cbp.gov/ruling/H331515", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Generalized System of Preferences"}}, {"claim_id": "claim_e3644d42dcd1845f65966b2c", "quote": "CBP held that for purposes of the Generalized System of Preferences (“GSP”), the assembly of a large number of fabricated components onto a printed circuit board in a process involving a considerable amount of time and skill resulted in a substantial transformation.", "url": "https://rulings.cbp.gov/ruling/H304910", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Generalized System of Preferences"}}]}]}

